window.CURSO.modulos.push(
{id: "M15", n: 3, t: "Servos, motores paso a paso y relés", d: "Servomotores de posición y de rotación continua, el controlador PCA9685, motores paso a paso y sus drivers, relés y otras cargas, y por qué no se conecta nada a la red eléctrica.", dep: ["M08", "M14"],
 obj: ["Controlar la posición de servomotores, también muchos a la vez.", "Mover motores paso a paso con precisión con ULN2003 y A4988.", "Conmutar cargas con relés y MOSFET de forma segura.", "Explicar los riesgos de la red eléctrica y las alternativas seguras."],
 prac: ["Barrera automática con servo.", "Reloj o plataforma giratoria con motor paso a paso.", "Bomba de agua de 5 V con relé."],
 mat: ["Servos SG90 y MG996R", "Controlador PCA9685", "Motor 28BYJ-48 con driver ULN2003", "NEMA17 con driver A4988 (opcional)", "Módulo de relé de 1 canal", "Minibomba sumergible de 5 V y tubo", "Sensor de humedad de suelo capacitivo", "Fuente de 5 V y 2 A"],
 pj: {t: "Riego automático", h: 2.5, d: "Un sistema que mide la humedad de la tierra de una maceta y activa una bomba de 5 V cuando está seca, con indicador de estado y protección contra el riego excesivo.",
  pasos: ["Calibra el sensor de humedad capacitivo (seco y mojado) y conviértelo a porcentaje.", "Conecta la minibomba de 5 V a través del relé (o de un MOSFET), con su propia alimentación y GND común.", "Programa: si la humedad baja del 30 %, riega 3 segundos; luego espera al menos 1 minuto antes de volver a medir para que el agua se reparta.", "Añade un límite de seguridad: como máximo 5 riegos por hora.", "Muestra el estado con LED (verde = bien, amarillo = regando, rojo = depósito vacío o error).", "Opcional: un servo que indique la humedad como una aguja.", "Prueba durante un día y anota los riegos."],
  crit: ["El sensor está calibrado en porcentaje.", "La bomba funciona a 5 V, sin conexión a la red.", "Hay tiempo de espera tras cada riego.", "Existe el límite de riegos por hora.", "Los LED indican el estado.", "La electrónica está protegida del agua."]},
 L: [
 {t: "Servomotores", h: 1, s: 1, p: "¿Cómo mueve un brazo robótico su codo exactamente a 90°?",
  o: ["Explicar cómo un servo mantiene una posición.", "Interpretar la señal de control y elegir entre servos de plástico y de metal."],
  x: ["Un **servomotor** (o servo) es un motor que va a la **posición** que se le indica y la **mantiene**. Por dentro tiene un pequeño **motor DC**, una **reductora** de engranajes, un **potenciómetro** unido al eje de salida (que mide la posición real) y un **circuito de control**. Este compara la posición pedida con la medida y mueve el motor hasta que coinciden: es un **control en lazo cerrado** (M16) en miniatura.",
   "### La señal",
   "Se controla con **un pulso cada 20 ms** (50 Hz). La **duración del pulso** indica el ángulo:",
   "- unos **1 ms → 0°**\n- **1,5 ms → 90°** (centro)\n- unos **2 ms → 180°**",
   "Los valores exactos varían entre modelos (muchos usan de 0,5 a 2,5 ms): por eso conviene calibrar los extremos y **no forzar** el servo contra sus topes (se oye un zumbido y se calienta).",
   "### Cables",
   "Tres cables: **marrón o negro = GND**, **rojo = alimentación** (4,8–6 V), **naranja, amarillo o blanco = señal**.",
   "### Modelos comunes",
   "- **SG90 (azul, plástico):** 9 g, unos 1,8 kg·cm. Ligero y barato; sus engranajes de plástico se rompen si se fuerzan. Para radares, pinzas pequeñas, indicadores.\n- **MG90S:** mismo tamaño con engranajes metálicos.\n- **MG996R (negro, grande):** engranajes metálicos, unos 10 kg·cm. Para brazos y patas.\n- **Servos digitales** y de alto par para robots más exigentes.",
   "### Consumo",
   "Un SG90 consume 100–250 mA al moverse y hasta unos 650 mA forzado; un MG996R puede superar **2 A**. Varios servos **no** pueden alimentarse desde el pin 5V del Arduino (lección siguiente)."],
  g: "servo", k: "Servo = motor + reductora + potenciómetro + control. Pulso cada 20 ms: 1 ms = 0°, 1,5 ms = 90°, 2 ms = 180°. Marrón GND, rojo +, naranja señal.",
  er: ["Forzar el servo contra sus topes.", "Mover el eje con la mano (rompe los engranajes de plástico)."],
  q: [["¿Qué mide el potenciómetro interno de un servo?", ["La temperatura", "La posición del eje", "La corriente", "La batería"], 1, "Así el control sabe dónde está."],
   ["¿Qué ángulo corresponde a un pulso de 1,5 ms?", ["0°", "90°", "180°", "45°"], 1, "Es la posición central."],
   ["¿Cada cuánto tiempo se envía el pulso de control?", ["1 ms", "20 ms", "1 s", "100 ms"], 1, "50 veces por segundo."],
   ["¿Qué cable del servo es la señal?", ["Marrón", "Rojo", "Naranja o amarillo", "Negro"], 2, "Marrón GND, rojo alimentación, naranja señal."],
   ["¿Qué servo elegirías para el hombro de un brazo que levanta peso?", ["SG90", "MG996R", "Un motor TT", "Un LED"], 1, "Tiene mucho más par y engranajes metálicos."]]},
 {t: "Controlar servos", h: 1.5, s: 1, p: "¿Cómo mueves 16 servos con un solo Arduino?",
  o: ["Usar la biblioteca Servo y moverlos suavemente.", "Alimentar varios servos correctamente y usar el PCA9685."],
  x: ["### La biblioteca Servo",
   "Viene incluida en el IDE: `#include <Servo.h>`, se crea un objeto `Servo brazo;`, se conecta con `brazo.attach(pin)` y se mueve con `brazo.write(ángulo)` (0–180). Para un control más fino, `brazo.writeMicroseconds(1500)`. Puede manejar hasta 12 servos en el Uno, en cualquier pin digital, aunque desactiva el PWM de los pines 9 y 10.",
   "### Movimientos suaves",
   "`write()` manda el servo a la nueva posición a toda velocidad, lo que provoca sacudidas y picos de corriente. Para moverlo suavemente, avanza **grado a grado** con pequeñas pausas (mejor con millis() para no bloquear).",
   "### Alimentación: la regla de oro",
   "Los servos **no** se alimentan del pin 5V del Arduino (salvo uno pequeño sin carga para probar). Usa una **fuente o batería aparte de 5–6 V** con suficiente corriente (para 4 SG90, al menos 2 A), un **condensador de 470–1000 µF** en la alimentación de los servos y **GND común** con el Arduino. Si los servos tiemblan, el Arduino se reinicia o se mueven solos, el 90 % de las veces es la alimentación.",
   "### El PCA9685",
   "Es un **controlador de 16 canales PWM por I2C** (dirección 0x40). Genera las señales de los servos por sí mismo, sin cargar al Arduino, con borneras para una fuente de alimentación separada. Se pueden encadenar varios (hasta 62 placas, 992 servos). Con la biblioteca **Adafruit PWM Servo Driver** se indica el pulso de cada canal. Es la solución estándar para brazos robóticos (M20) y robots con patas."],
  c: {l: "cpp", t: "// Barrera automática con un servo en el pin 9 y movimiento suave\n#include <Servo.h>\nServo barrera;\nint angulo = 0;\n\nvoid moverSuave(int destino) {\n  while (angulo != destino) {\n    angulo += (destino > angulo) ? 1 : -1;\n    barrera.write(angulo);\n    delay(8);                     // velocidad del movimiento\n  }\n}\n\nvoid setup() {\n  barrera.attach(9);\n  barrera.write(angulo);\n  pinMode(2, INPUT_PULLUP);       // botón para abrir\n}\n\nvoid loop() {\n  if (digitalRead(2) == LOW) {\n    moverSuave(90);               // abrir\n    delay(3000);\n    moverSuave(0);                // cerrar\n  }\n}"},
  pr: {m: ["Arduino", "servo SG90", "pulsador", "fuente o porta-pilas de 4 AA para el servo", "condensador de 470 µF"], p: ["Alimenta el servo desde las pilas, con GND común y el condensador.", "Carga el ejemplo de la barrera.", "Añade un sensor ultrasónico para que se abra cuando algo se acerque a menos de 15 cm.", "Si tienes un PCA9685, mueve dos servos con él y su biblioteca."], e: "La barrera se abre suavemente al pulsar o al acercarse un objeto.", sim: "Wokwi y Tinkercad incluyen servos."},
  er: ["Alimentar varios servos desde el Arduino.", "Olvidar el GND común con la fuente de los servos."],
  q: [["¿Qué función mueve un servo a 45° con la biblioteca Servo?", ["servo.attach(45)", "servo.write(45)", "analogWrite(45)", "servo.read(45)"], 1, "write recibe el ángulo."],
   ["¿Cuál es la causa más común de que los servos tiemblen?", ["El código", "Una alimentación insuficiente", "El color del cable", "La temperatura"], 1, "Necesitan una fuente aparte con suficiente corriente."],
   ["¿Cuántos canales tiene un PCA9685?", {n: 16, tol: 0, u: ""}, null, "16 salidas PWM por I2C."],
   ["¿Por qué mover el servo grado a grado?", ["Para que el movimiento sea suave", "Porque write no funciona", "Para ahorrar memoria", "No hace falta"], 0, "Evita sacudidas y picos de corriente."],
   ["¿Qué dirección I2C usa por defecto el PCA9685?", ["0x3C", "0x40", "0x68", "0x76"], 1, "0x40."]]},
 {t: "Servos de rotación continua", h: 1, p: "¿Se puede usar un servo como motor de rueda?",
  o: ["Explicar en qué se diferencia un servo de rotación continua.", "Controlar su velocidad y sentido, y conocer sus límites."],
  x: ["Un **servo de rotación continua** (como el FS90R o el SM-S4303R) parece un servo normal, pero **no tiene topes** ni realimentación de posición: puede girar sin fin. Por dentro, el potenciómetro está fijado en su posición central (o sustituido por dos resistencias).",
   "### Cómo se controla",
   "Usa la misma señal y la misma biblioteca, pero el valor ya no es un ángulo, sino una **velocidad y un sentido**:",
   "- `write(90)` (pulso de 1,5 ms) → **parado**.\n- `write(0)` → máxima velocidad en un sentido.\n- `write(180)` → máxima velocidad en el otro.\n- Valores intermedios → velocidades intermedias (de forma poco lineal).",
   "Si con `write(90)` sigue girando despacio, hay que **calibrar el punto muerto**: muchos tienen un pequeño potenciómetro accesible por un agujero, o se busca por código el valor exacto (89, 91…) en el que se detiene.",
   "### Ventajas e inconvenientes",
   "- **Ventajas:** incluyen motor, reductora y driver; se conectan directamente con un solo cable de señal, sin puente H. Muy cómodos para robots pequeños y para principiantes.\n- **Inconvenientes:** son lentos, tienen poca potencia, su velocidad no es precisa y **no saben cuánto han girado** (no tienen encoder). Para robots más rápidos o precisos, son mejores los motorreductores con driver y encoder.",
   "También se puede convertir un servo normal en uno de rotación continua (quitando el tope y fijando el potenciómetro), pero es delicado y se pierde la garantía.",
   "**No confundas:** un servo de posición (0–180°) que se fuerza a girar más allá de su tope **se rompe**. Comprueba qué tipo tienes antes de usarlo en una rueda."],
  c: {l: "cpp", t: "// Servo de rotación continua: adelante, parar, atrás\n#include <Servo.h>\nServo rueda;\nconst int PARADO = 90;   // calibra: el valor exacto donde se detiene\n\nvoid setup() { rueda.attach(9); }\n\nvoid loop() {\n  rueda.write(PARADO + 40);  delay(2000);   // un sentido, velocidad media\n  rueda.write(PARADO);       delay(1000);   // parado\n  rueda.write(PARADO - 40);  delay(2000);   // el otro sentido\n  rueda.write(PARADO);       delay(1000);\n}"},
  er: ["Usar un servo de posición como si fuera de rotación continua.", "No calibrar el punto muerto y tener un robot que nunca se detiene del todo."],
  q: [["En un servo de rotación continua, write(90) significa…", ["90°", "Parado", "Máxima velocidad", "Error"], 1, "El centro de la señal es el punto muerto."],
   ["¿Qué le falta a un servo de rotación continua frente a uno de posición?", ["El motor", "Los topes y la realimentación de posición", "Los cables", "La reductora"], 1, "Por eso puede girar sin fin."],
   ["¿Qué ventaja tienen para un robot principiante?", ["Son muy rápidos", "No necesitan puente H ni driver", "Miden la distancia", "Tienen WiFi"], 1, "Incluyen todo; solo necesitan la señal."],
   ["Si el servo sigue girando despacio en write(90), hay que…", ["Cambiar la batería", "Calibrar el punto muerto", "Cortar un cable", "Usar delay"], 1, "Buscar el valor exacto donde se detiene."],
   ["¿Qué pasa si fuerzas un servo de posición a girar sin fin?", ["Funciona bien", "Se rompe", "Se convierte en continuo", "Se acelera"], 1, "Tiene topes mecánicos."]]},
 {t: "Motores paso a paso", h: 1.5, s: 1, p: "¿Cómo mueve una impresora 3D su cabezal con precisión de décimas de milímetro?",
  o: ["Explicar el funcionamiento de un motor paso a paso.", "Distinguir motores unipolares y bipolares, pasos y micropasos."],
  x: ["Un **motor paso a paso** (*stepper*) gira en **pasos fijos**: con cada pulso de control avanza un ángulo exacto. Tiene varias bobinas alrededor de un rotor con dientes magnéticos; activándolas en secuencia, el rotor salta de una posición a la siguiente.",
   "### Por qué son útiles",
   "- **Posicionamiento preciso sin sensores:** si cuentas los pasos, sabes dónde está (control en **lazo abierto**). Un NEMA17 típico da **200 pasos por vuelta** (1,8° por paso).\n- **Par en reposo:** mantienen la posición con fuerza mientras las bobinas están alimentadas.\n- Por eso están en **impresoras 3D**, máquinas CNC, escáneres, cámaras motorizadas, relojes y plataformas giratorias.",
   "### Inconvenientes",
   "- Si se les pide demasiada velocidad o par, **pierden pasos** y ya no saben dónde están (se resuelve con un final de carrera para el *homing*).\n- **Consumen corriente aunque estén quietos.**\n- A altas velocidades su par cae mucho.",
   "### Unipolares y bipolares",
   "- **Unipolar** (5 o 6 cables, como el **28BYJ-48**): bobinas con toma central; fáciles de controlar con transistores simples (driver ULN2003).\n- **Bipolar** (4 cables, como el **NEMA17**): más par para su tamaño, pero necesitan invertir la corriente en cada bobina (un puente H por bobina, como el driver A4988).",
   "### Micropasos",
   "Los drivers modernos pueden alimentar las bobinas con corrientes intermedias para dividir cada paso en **micropasos** (1/2, 1/4, 1/16…). El movimiento es más suave y silencioso, y la resolución mayor: 200 pasos × 16 = 3200 micropasos por vuelta.",
   "### El 28BYJ-48",
   "Pequeño, de 5 V y muy barato, con una reductora interna de aproximadamente 1:64: da unos **2048 pasos por vuelta** (en modo de paso completo; 4096 en medio paso). Es lento (unas 10–15 RPM) pero perfecto para aprender."],
  k: "Paso a paso: gira en pasos exactos (NEMA17: 200 pasos/vuelta). Posición sin sensores contando pasos. Unipolar → ULN2003; bipolar → A4988.",
  ej: ["**Problema:** ¿cuántos pasos necesita un NEMA17 (200 pasos/vuelta) con micropasos de 1/16 para girar 90°?", "Pasos por vuelta = 200 × 16 = 3200. Un cuarto de vuelta = **800 micropasos**."],
  er: ["Pedir demasiada velocidad y que pierda pasos.", "Dejar el motor alimentado parado mucho tiempo: se calienta."],
  q: [["¿Cuántos grados gira por paso un motor de 200 pasos por vuelta?", {n: 1.8, tol: 0.01, u: "°"}, null, "360 / 200 = 1,8°."],
   ["¿Qué ventaja principal tiene un motor paso a paso?", ["Es el más rápido", "Posicionamiento preciso contando pasos", "No consume energía", "No necesita driver"], 1, "Sabe dónde está sin sensores."],
   ["¿Qué pasa si se le pide demasiada velocidad o carga?", ["Gira más rápido", "Pierde pasos", "Se convierte en servo", "Nada"], 1, "Deja de seguir la secuencia y pierde la posición."],
   ["¿Cuántos cables tiene normalmente un motor bipolar?", {n: 4, tol: 0, u: ""}, null, "Dos bobinas, dos cables cada una."],
   ["Con micropasos de 1/8 en un motor de 200 pasos, ¿cuántos micropasos hay por vuelta?", {n: 1600, tol: 0, u: ""}, null, "200 × 8 = 1600."]]},
 {t: "Drivers de paso a paso: ULN2003 y A4988", h: 1.5, p: "¿Cómo se ajusta la corriente de un motor de impresora 3D?",
  o: ["Controlar un 28BYJ-48 con el ULN2003.", "Conectar y ajustar un A4988 para un NEMA17."],
  x: ["### ULN2003 con el 28BYJ-48",
   "El ULN2003 contiene siete transistores Darlington con diodos de protección. El módulo típico tiene 4 entradas (IN1–IN4), 4 LED que muestran qué bobina está activa y un conector para el motor. Se alimenta a 5 V (desde una fuente aparte si mueves más de un motor). Con la biblioteca **Stepper** (incluida) o la más completa **AccelStepper** se indica cuántos pasos dar y a qué velocidad. Ojo: el orden de los pines en el código suele ser **IN1, IN3, IN2, IN4**.",
   "### A4988 (o DRV8825) con un NEMA17",
   "Driver bipolar diminuto, el de muchas impresoras 3D. Solo necesita **dos pines**: **STEP** (cada pulso = un paso) y **DIR** (sentido). Otros pines importantes:",
   "- **VMOT y GND:** alimentación de los motores (8–35 V), con un **condensador de 100 µF** junto al driver (imprescindible: protege de picos).\n- **VDD y GND:** lógica de 3,3–5 V.\n- **1A, 1B, 2A, 2B:** las dos bobinas del motor.\n- **MS1, MS2, MS3:** micropasos.\n- **ENABLE, SLEEP, RESET:** SLEEP y RESET se unen entre sí para que funcione.",
   "### Ajustar el límite de corriente",
   "El A4988 tiene un **potenciómetro** que fija la corriente máxima por bobina. Hay que ajustarlo **antes** de usar el motor, según su corriente nominal: se mide el voltaje de referencia (VREF) entre el potenciómetro y GND y se aplica la fórmula de la hoja de datos de tu módulo (en muchos, **corriente ≈ VREF × 2,5**). Demasiada corriente sobrecalienta el driver y el motor; poca, hace que pierda pasos.",
   "### Normas",
   "- **Nunca conectes ni desconectes el motor con el driver alimentado:** se destruye el driver.\n- El A4988 se calienta: usa su disipador.\n- Para mover varios motores con aceleración y a la vez, usa **AccelStepper**."],
  c: {l: "cpp", t: "// NEMA17 con A4988: STEP en el pin 3, DIR en el pin 4 (paso completo)\nconst int STEP = 3, DIR = 4;\nconst int PASOS_VUELTA = 200;\n\nvoid pasos(int n, bool sentido, int usPorPaso) {\n  digitalWrite(DIR, sentido);\n  for (int i = 0; i < n; i++) {\n    digitalWrite(STEP, HIGH);\n    delayMicroseconds(usPorPaso / 2);\n    digitalWrite(STEP, LOW);\n    delayMicroseconds(usPorPaso / 2);\n  }\n}\n\nvoid setup() {\n  pinMode(STEP, OUTPUT);\n  pinMode(DIR, OUTPUT);\n}\n\nvoid loop() {\n  pasos(PASOS_VUELTA, HIGH, 2000);   // una vuelta en 0,4 s\n  delay(1000);\n  pasos(PASOS_VUELTA / 4, LOW, 4000); // un cuarto de vuelta al revés, más lento\n  delay(1000);\n}"},
  pr: {m: ["Arduino", "28BYJ-48 con ULN2003", "fuente de 5 V", "opcional: NEMA17, A4988, fuente de 12 V y condensador de 100 µF"], p: ["Conecta el 28BYJ-48 al ULN2003 y este a los pines 8–11.", "Carga el ejemplo «stepper_oneRevolution» de la biblioteca Stepper con 2048 pasos por vuelta.", "Haz que gire exactamente 90° cuando pulses un botón.", "Si tienes NEMA17: ajusta VREF del A4988 con el multímetro antes de conectar el motor y prueba el ejemplo."], e: "El motor gira exactamente los ángulos pedidos.", sim: "Wokwi incluye motores paso a paso con el driver A4988."},
  sg: "No conectes ni desconectes el motor con el driver encendido. El A4988 y el motor pueden calentarse mucho: no los toques mientras funcionan.",
  er: ["Usar el orden de pines IN1, IN2, IN3, IN4 con la biblioteca Stepper y que el motor solo vibre.", "No ajustar la corriente del A4988."],
  q: [["¿Cuántos pines de control necesita el A4988 para mover el motor?", {n: 2, tol: 0, u: ""}, null, "STEP y DIR."],
   ["¿Qué hace cada pulso en el pin STEP?", ["Cambia el sentido", "Avanza un paso (o micropaso)", "Apaga el motor", "Mide la corriente"], 1, "Un pulso, un paso."],
   ["¿Qué se ajusta con el potenciómetro del A4988?", ["La velocidad", "El límite de corriente", "El número de pasos", "El voltaje de la lógica"], 1, "Se ajusta midiendo VREF."],
   ["¿Qué componente es imprescindible junto a VMOT?", ["Un LED", "Un condensador de unos 100 µF", "Una LDR", "Un zumbador"], 1, "Protege al driver de picos de voltaje."],
   ["¿Qué no se debe hacer nunca con un A4988 alimentado?", ["Medir VREF", "Conectar o desconectar el motor", "Enviar pulsos", "Cambiar DIR"], 1, "Destruye el driver."]]},
 {t: "Relés", h: 1.5, s: 1, p: "¿Cómo puede un Arduino de 5 V encender una bomba que tiene su propia batería?",
  o: ["Explicar cómo funciona un relé y sus contactos NA y NC.", "Usar un módulo de relé con seguridad en circuitos de bajo voltaje."],
  x: ["Un **relé** es un **interruptor accionado por un electroimán**. Cuando circula corriente por su **bobina**, el electroimán atrae una pieza metálica que cambia la posición de los **contactos**. Lo interesante es que el circuito de la bobina y el de los contactos están **separados eléctricamente**: un circuito pequeño controla otro independiente.",
   "### Los contactos",
   "- **COM (común):** el terminal que se mueve.\n- **NA (normalmente abierto, NO):** conectado a COM **solo cuando el relé está activado**.\n- **NC (normalmente cerrado):** conectado a COM **cuando el relé está desactivado**.",
   "Para encender algo al activar el relé, se usa **COM y NA**.",
   "### El módulo de relé",
   "La bobina de un relé de 5 V consume unos 70–90 mA (demasiado para un pin) y produce picos al apagarse. Por eso se usan **módulos** que incluyen el transistor, el diodo de protección, un LED indicador y a menudo un **optoacoplador** (M05). Pines: **VCC, GND, IN**. Atención: muchos módulos son de **lógica invertida** (*active low*): el relé se activa con `digitalWrite(IN, LOW)`.",
   "### Límites y cuidados",
   "- Los relés tienen un **límite de corriente y voltaje** en sus contactos (impreso en la cápsula), pero en este curso **solo se usan con cargas de bajo voltaje (12 V CC o menos)**.\n- Son **lentos** (unos 10 ms) y tienen vida mecánica limitada: no sirven para PWM.\n- Al conmutar motores o bombas, pon un diodo de protección también en la carga.\n- Para cargas de corriente continua, a menudo es mejor un **MOSFET** (M05): silencioso, sin desgaste y admite PWM.",
   "Las **regletas de relés** de 4 u 8 canales permiten controlar varias cargas: luces LED de 12 V, ventiladores, bombas, una cerradura de solenoide."],
  c: {l: "cpp", t: "// Módulo de relé de lógica invertida en el pin 7: bomba de 5 V 3 s cada 10 s\nconst int RELE = 7;\nconst bool ACTIVO = LOW;     // en módulos «active low»\n\nvoid setup() {\n  digitalWrite(RELE, !ACTIVO);   // empezar desactivado ANTES de configurarlo como salida\n  pinMode(RELE, OUTPUT);\n}\n\nvoid loop() {\n  digitalWrite(RELE, ACTIVO);    // bomba encendida\n  delay(3000);\n  digitalWrite(RELE, !ACTIVO);   // bomba apagada\n  delay(10000);\n}"},
  pr: {m: ["Arduino", "módulo de relé de 1 canal", "minibomba sumergible de 5 V con tubo", "porta-pilas de 4 AA o fuente de 5 V", "recipiente con agua"], p: ["Conecta el módulo: VCC, GND e IN al pin 7.", "Conecta la bomba con su alimentación a través de COM y NA.", "Carga el programa y escucha el clic del relé.", "Comprueba si tu módulo es de lógica normal o invertida.", "Sustituye el relé por un MOSFET y regula el caudal con PWM."], e: "La bomba se enciende 3 s cada 10 s.", sim: "Wokwi y Tinkercad tienen módulos de relé."},
  sg: "En este curso los relés solo conmutan cargas de 12 V o menos. Mantén la electrónica lejos del agua y la bomba sumergida solo en su recipiente.",
  er: ["Conectar la carga a NC en lugar de NA.", "No saber que el módulo es de lógica invertida y que el relé se active al arrancar."],
  q: [["¿Qué activa los contactos de un relé?", ["Un electroimán", "La luz", "El calor", "Un muelle solo"], 0, "La bobina atrae la pieza móvil."],
   ["Para que una carga se encienda al activar el relé, usas…", ["COM y NC", "COM y NA", "VCC y GND", "IN y GND"], 1, "NA se cierra al activar."],
   ["En un módulo «active low», el relé se activa con…", ["HIGH", "LOW"], 1, "Lógica invertida."],
   ["¿Por qué un relé no sirve para PWM?", ["Es demasiado rápido", "Es lento y tiene desgaste mecánico", "No tiene bobina", "Necesita WiFi"], 1, "Tarda unos 10 ms en conmutar."],
   ["¿Qué ventaja tiene el MOSFET frente al relé para cargas de corriente continua?", ["Aísla mejor", "Es silencioso, sin desgaste y admite PWM", "Funciona con alterna", "Es más grande"], 1, "No tiene partes móviles."]]},
 {t: "Bombas, solenoides y ventiladores", h: 1, p: "¿Cómo se abre una cerradura eléctrica?",
  o: ["Conectar cargas inductivas comunes con MOSFET y diodo.", "Dimensionar la alimentación de estas cargas."],
  x: ["Muchas cargas útiles en robótica y domótica son **bobinas** o **motores**, es decir, **cargas inductivas**. Todas siguen las mismas reglas: necesitan **más corriente** de la que da un pin, producen **picos de voltaje** al apagarse y generan **ruido**.",
   "### Las cargas más comunes",
   "- **Minibombas de agua** (3–6 V, sumergibles, unos 100–300 mA): riego, fuentes, dispensadores.\n- **Bombas peristálticas** (12 V): dosifican líquidos con precisión.\n- **Solenoides** (5–12 V): un émbolo que sale o entra al activarse; cerraduras eléctricas, pulsadores robóticos, válvulas de agua. Pueden pedir **1 A o más**.\n- **Ventiladores** de 5 V o 12 V: refrigeración y control de clima; los de 4 hilos admiten control PWM propio y dan señal de velocidad.\n- **Vibradores** (motores con masa excéntrica): avisos táctiles.\n- **Tiras de LED** de 12 V (no son inductivas, pero consumen mucho).",
   "### El circuito universal",
   "Para casi todas: un **MOSFET de nivel lógico** (IRLZ44N) en el lado bajo, con la carga entre +V y el drenador, **diodo** en paralelo con la carga (cátodo a +V), resistencia de 220 Ω en la puerta y 10 kΩ de la puerta a GND, **GND común** y la alimentación adecuada para la carga. Con PWM, puedes regular la velocidad de un ventilador o el caudal de una bomba.",
   "### Cuidados especiales",
   "- **Solenoides:** muchos no están pensados para estar activados mucho tiempo (se calientan); revisa su ciclo de trabajo. Las cerraduras de solenoide deben tener una apertura mecánica de emergencia.\n- **Bombas:** la mayoría **no deben funcionar en seco**; se estropean. Pon un sensor de nivel en el depósito.\n- **Agua y electrónica:** separa físicamente el depósito de la electrónica, usa cajas y fija bien los tubos."],
  c: {l: "cpp", t: "// Ventilador de 12 V con MOSFET en el pin 9, según la temperatura (DHT22 en el pin 4)\n#include <DHT.h>\nDHT dht(4, DHT22);\nconst int VENTILADOR = 9;\n\nvoid setup() { pinMode(VENTILADOR, OUTPUT); dht.begin(); }\n\nvoid loop() {\n  float t = dht.readTemperature();\n  if (!isnan(t)) {\n    int pwm = 0;\n    if (t > 26) pwm = map(constrain((int)t, 26, 32), 26, 32, 120, 255);  // más calor, más velocidad\n    analogWrite(VENTILADOR, pwm);\n  }\n  delay(2000);\n}"},
  sg: "Trabaja solo con cargas de 12 V o menos y con fuentes certificadas. No dejes solenoides activados más tiempo del indicado ni bombas funcionando en seco.",
  er: ["Olvidar el diodo en un solenoide: el pico destruye el MOSFET.", "Hacer funcionar una bomba sin agua."],
  q: [["¿Qué tienen en común bombas, solenoides y motores?", ["Son cargas inductivas", "Funcionan con luz", "No consumen", "Son sensores"], 0, "Contienen bobinas."],
   ["¿Qué componente protege al MOSFET del pico de un solenoide?", ["Un diodo en paralelo con la carga", "Un LED", "Una LDR", "Un potenciómetro"], 0, "El diodo absorbe la energía de la bobina."],
   ["¿Qué no deben hacer la mayoría de las minibombas?", ["Funcionar en seco", "Funcionar con 5 V", "Mover agua", "Usar MOSFET"], 0, "Se estropean sin agua."],
   ["¿Cómo regulas la velocidad de un ventilador de 12 V con Arduino?", ["Con un divisor de voltaje", "Con PWM a través de un MOSFET", "Con un relé y PWM", "No se puede"], 1, "El MOSFET admite PWM."],
   ["¿Qué debe tener una cerradura de solenoide por seguridad?", ["Un LED", "Una apertura mecánica de emergencia", "WiFi", "Un sensor de luz"], 1, "Para poder abrir si falla la electricidad."]]},
 {t: "Cargas de la red eléctrica: por qué no", h: 1, s: 1, p: "Has visto en internet un vídeo de alguien que controla la lámpara de su casa con un Arduino y un relé. ¿Por qué este curso no lo hace?",
  o: ["Explicar los riesgos de manipular la red eléctrica.", "Conocer alternativas seguras para controlar aparatos de la casa."],
  x: ["Muchos módulos de relé llevan impreso «10A 250VAC», y abundan los tutoriales que conectan lámparas, enchufes o electrodomésticos a un Arduino. **En este curso no se hace nunca**, y estas son las razones:",
   "### Los riesgos",
   "- **Descarga eléctrica:** 110–240 V de corriente alterna pueden provocar quemaduras, paradas cardíacas y la muerte. Basta con tocar un tornillo de la bornera del relé o una soldadura de la placa.\n- **Incendio:** conexiones flojas, cables finos, relés de baja calidad (muchos módulos baratos no aguantan realmente su corriente nominal) y placas sin distancias de aislamiento suficientes pueden sobrecalentarse.\n- **Placas de prototipos:** las protoboard, las placas perforadas y los cables Dupont **no están diseñados** para la red eléctrica.\n- **Normas y seguros:** las instalaciones eléctricas deben cumplir normativas y las suele hacer un **electricista certificado**. Un aparato casero que cause un incendio puede dejar a la familia sin cobertura del seguro.",
   "### Alternativas seguras",
   "- **Enchufes inteligentes certificados** (WiFi o Zigbee): se enchufan a la pared y el aparato se enchufa en ellos. Muchos se pueden controlar desde Home Assistant, por MQTT o con una API local, sin abrir nada (M21).\n- **Relés y fuentes en caja cerrada y certificados** para carril DIN, **instalados por un profesional**.\n- **Trabajar a bajo voltaje:** iluminación LED de 12 V o 5 V, ventiladores de 12 V, bombas de 5 V. Con ellos puedes hacer prácticamente cualquier proyecto de domótica educativo.\n- **Módulos IR o de radio** que imitan el mando del aparato (aire acondicionado, televisor).",
   "### Regla del curso",
   "Si un proyecto «necesita» la red eléctrica, **se rediseña a bajo voltaje** o se usa un **dispositivo comercial certificado sin abrirlo**. Sin excepciones."],
  k: "La red eléctrica (110–240 V CA) puede matar e incendiar. En el curso: solo bajo voltaje, o enchufes inteligentes certificados sin abrirlos.",
  sg: "Nunca abras, modifiques ni conectes nada a la red eléctrica. Si ves un cable pelado o un enchufe dañado en casa, no lo toques y avisa a un adulto.",
  er: ["Fiarse del «250VAC» impreso en un relé barato.", "Pensar que «con cuidado» se puede trabajar con la red en una protoboard."],
  q: [["¿Por qué no se usan relés con la red eléctrica en este curso?", ["Porque no funcionan", "Por el riesgo de descarga e incendio", "Porque son caros", "Porque no hacen clic"], 1, "La red puede matar y provocar incendios."],
   ["¿Cuál es una alternativa segura para encender una lámpara de casa?", ["Un relé en una protoboard", "Un enchufe inteligente certificado", "Cables Dupont", "Un MOSFET suelto"], 1, "Se usa sin abrirlo."],
   ["¿Están diseñadas las protoboard para la red eléctrica?", ["Sí", "No"], 1, "Su aislamiento y contactos no son adecuados."],
   ["Si un proyecto parece necesitar la red eléctrica, en el curso se…", ["Conecta con cuidado", "Rediseña a bajo voltaje o usa un dispositivo certificado", "Hace de noche", "Prueba sin fusible"], 1, "Es la regla del curso."],
   ["¿Quién debe hacer instalaciones conectadas a la red?", ["Cualquiera con tutoriales", "Un electricista certificado", "Un robot", "Nadie"], 1, "Requieren formación y normativa."]]}
 ]},

{id: "M16", n: 3, t: "Mecánica y control", d: "Materiales y estructuras, ruedas, engranajes y poleas, fabricación digital, lazo abierto y cerrado, control PID, máquinas de estados e integración.", dep: ["M14", "M13"],
 obj: ["Elegir materiales y transmisiones para un robot.", "Diseñar piezas sencillas para impresión 3D o corte láser.", "Diferenciar control en lazo abierto y cerrado.", "Implementar y ajustar un controlador PID.", "Organizar el comportamiento de un robot como máquina de estados."],
 prac: ["Control de velocidad con encoder y PID.", "Máquina de estados para una puerta automática."],
 mat: ["Plataforma 2WD con encoders", "Cartón pluma, MDF o acrílico", "Tornillos M3, separadores, bridas", "Herramientas", "Acceso opcional a impresora 3D"],
 pj: {t: "Robot que avanza exactamente 1 metro", h: 2, d: "Con encoders y control PID, tu robot debe avanzar exactamente 1 m en línea recta y detenerse, con un error menor de 2 cm.",
  pasos: ["Calcula los centímetros por pulso de tus encoders y comprueba el valor rodando la rueda a mano.", "Programa un PID de velocidad para cada rueda (objetivo en pulsos por segundo).", "Añade un control que iguale los pulsos de ambas ruedas para ir recto.", "Organiza el programa en una máquina de estados: ESPERA, ACELERAR, CRUCERO, FRENAR, FIN.", "Frena progresivamente al acercarte al objetivo.", "Haz 5 pruebas, mide el error de distancia y la desviación lateral y anótalos en una tabla.", "Explica cómo ajustaste Kp, Ki y Kd."],
  crit: ["Usa encoders y PID.", "El programa es una máquina de estados.", "El error medio de distancia es menor de 2 cm.", "La desviación lateral es razonable (menos de 5 cm).", "Hay una tabla con 5 pruebas.", "Se explica el ajuste del PID."]},
 L: [
 {t: "Materiales y estructuras", h: 1, p: "¿De qué fabricarías el chasis de tu primer robot si no tienes impresora 3D?",
  o: ["Comparar materiales para construir robots.", "Aplicar ideas básicas de rigidez y unión de piezas."],
  x: ["La estructura (el **chasis**) sostiene todo: motores, baterías, placas y sensores. Debe ser **rígida** (que no se doble), **ligera** (cada gramo de más gasta batería) y **fácil de modificar y reparar**.",
   "### Materiales",
   "- **Cartón y cartón pluma:** gratis o muy baratos, se cortan con cúter. Perfectos para prototipos rápidos y maquetas (la casa inteligente del M21). Poco duraderos y sensibles a la humedad.\n- **Madera contrachapada y MDF (3–5 mm):** baratos, rígidos, fáciles de taladrar y atornillar; ideales para corte láser.\n- **Acrílico (metacrilato):** transparente y vistoso, se corta con láser; frágil ante golpes y se agrieta al atornillar con fuerza.\n- **Plástico impreso en 3D (PLA, PETG):** formas a medida, piezas que encajan exactamente con tus motores y sensores.\n- **Aluminio:** perfiles y chapas muy resistentes y ligeros; requiere herramientas de metal.\n- **Piezas de construcción** (kits educativos, piezas metálicas perforadas): reutilizables, rápidas.\n- **Materiales reciclados:** tapas, botellas, cajas de plástico, CD como ruedas…",
   "### Rigidez",
   "Una placa plana se dobla fácilmente; doblar un borde, añadir **nervios** o formar **triángulos** la hace mucho más rígida. Las estructuras en forma de caja o con escuadras resisten mejor.",
   "### Uniones",
   "- **Tornillos M3 con tuercas y separadores** (*standoffs*): el estándar en robótica; permiten desmontar y apilar placas en «pisos».\n- **Bridas:** rápidas para cables y piezas ligeras.\n- **Silicona caliente:** muy cómoda para prototipos, pero poco duradera y difícil de deshacer.\n- **Cinta de doble cara y velcro:** para baterías y placas que se quitan a menudo.",
   "### Distribución",
   "Coloca lo **más pesado (la batería) abajo y cerca del eje** de las ruedas para que el robot sea estable y tenga tracción. Deja accesibles el interruptor, el puerto USB y la batería."],
  k: "Rígido, ligero y reparable. Prototipa en cartón; luego MDF, acrílico o impresión 3D. Tornillos M3 y separadores. Batería abajo y centrada.",
  er: ["Fijarlo todo con silicona y no poder reparar nada.", "Colocar la batería arriba y lejos de las ruedas: el robot vuelca."],
  q: [["¿Qué material es ideal para prototipos rápidos y baratos?", ["Aluminio", "Cartón o cartón pluma", "Acero", "Vidrio"], 1, "Se corta con cúter y es casi gratis."],
   ["¿Qué tornillos son el estándar en robótica pequeña?", ["M3", "M20", "De madera grandes", "Remaches"], 0, "M3 con tuercas y separadores."],
   ["¿Dónde conviene colocar la batería?", ["Arriba del todo", "Abajo y cerca del eje de las ruedas", "Colgando por fuera", "Da igual"], 1, "Más estabilidad y tracción."],
   ["¿Qué forma aumenta la rigidez de una estructura?", ["Círculos sueltos", "Triángulos y nervios", "Placas finas planas", "Agujeros grandes"], 1, "Los triángulos no se deforman."],
   ["¿Qué problema tiene el acrílico?", ["Es opaco", "Es frágil y se agrieta al apretar tornillos", "No se puede cortar", "Pesa mucho"], 1, "Hay que atornillarlo con cuidado."]]},
 {t: "Ruedas, engranajes y poleas", h: 1.5, p: "¿Por qué una bicicleta tiene varios platos y piñones?",
  o: ["Calcular relaciones de transmisión con engranajes y poleas.", "Elegir ruedas y apoyos para un robot móvil."],
  x: ["Las **transmisiones** llevan el movimiento del motor a donde se necesita y cambian la relación entre **velocidad** y **par** (M14).",
   "### Engranajes",
   "Ruedas dentadas que encajan. Si un engranaje de **10 dientes** (el del motor, llamado piñón) mueve uno de **30 dientes**, la relación es **30:10 = 3:1**: el segundo gira **3 veces más despacio** con unas **3 veces más par**, y **en sentido contrario**. Para invertir de nuevo el sentido se añade un engranaje intermedio. Con varias parejas en cadena las relaciones se **multiplican** (así se consiguen reductoras 1:48 o 1:100).",
   "Otros tipos: **tornillo sinfín** (relaciones muy grandes y no se puede mover desde la salida: ideal para brazos que deben mantener la posición), **piñón y cremallera** (convierte giro en movimiento lineal), **engranajes cónicos** (cambian la dirección 90°).",
   "### Poleas y correas",
   "Funcionan igual que los engranajes pero a distancia, **sin invertir el sentido**: relación = diámetro de la polea conducida / diámetro de la motriz. Las **correas dentadas** (GT2) no patinan y son las de las impresoras 3D.",
   "### Ruedas",
   "- **Diámetro:** más grande = más velocidad y supera mejor obstáculos, pero exige más par.\n- **Agarre:** neumáticos de goma; las ruedas de plástico liso patinan.\n- **Ruedas locas** (*caster*) o bolas: el tercer apoyo de un robot diferencial. Una bola de metal funciona bien en suelos lisos; las ruedas giratorias, en alfombras.\n- **Orugas:** gran tracción en terreno difícil, pero giran «arrastrando» y consumen más.\n- **Ruedas omnidireccionales y Mecanum:** permiten moverse de lado; más complejas de controlar.",
   "### Fricción y holguras",
   "Los ejes deben girar libres pero sin bailar. Un rozamiento extra gasta batería y hace que un motor vaya más lento que el otro."],
  k: "Relación = dientes (o diámetro) de salida / de entrada. Reduce la velocidad y multiplica el par. Engranajes invierten el sentido; poleas no.",
  ej: ["**Problema:** un motor a 300 RPM mueve un piñón de 12 dientes que engrana con uno de 36.", "Relación = 36/12 = 3. Salida = 300/3 = **100 RPM**, con unas 3 veces más par y en sentido contrario."],
  er: ["Olvidar que cada pareja de engranajes invierte el sentido.", "Ruedas lisas que patinan y arruinan la odometría."],
  q: [["Un piñón de 10 dientes mueve un engranaje de 40. ¿Relación de reducción?", {n: 4, tol: 0, u: ":1"}, null, "40/10 = 4: gira 4 veces más despacio."],
   ["Si el motor gira a 200 RPM con esa reducción 4:1, ¿cuántas RPM da la salida?", {n: 50, tol: 0, u: "RPM"}, null, "200/4 = 50 RPM."],
   ["¿Qué transmisión mantiene la posición sin poder moverse desde la salida?", ["Correa", "Tornillo sinfín", "Polea lisa", "Rueda loca"], 1, "El sinfín es irreversible en la práctica."],
   ["Dos engranajes engranados giran…", ["En el mismo sentido", "En sentidos contrarios"], 1, "Cada pareja invierte el sentido."],
   ["¿Qué convierte giro en movimiento lineal?", ["Piñón y cremallera", "Rueda loca", "Polea", "Sinfín con corona"], 0, "La cremallera es un engranaje recto."]]},
 {t: "Fabricación digital: impresión 3D y corte láser", h: 1.5, p: "¿Cómo se fabrica una pieza a medida para sujetar un sensor exactamente donde quieres?",
  o: ["Describir el proceso de impresión 3D y de corte láser.", "Diseñar una pieza sencilla en Tinkercad 3D."],
  x: ["La **fabricación digital** convierte un diseño de la computadora en una pieza real. Ha revolucionado la robótica de aficionados: ya no dependes de piezas comerciales.",
   "### Impresión 3D (FDM)",
   "La impresora más común funde un **filamento** de plástico y lo deposita **capa a capa** (de 0,1 a 0,3 mm) hasta formar la pieza. El flujo de trabajo:",
   "- **1. Diseño 3D:** en **Tinkercad** (en el navegador, combinando formas básicas: ideal para empezar), **FreeCAD** o **Fusion 360**.\n- **2. Exportar** a STL.\n- **3. Laminar** con un programa como **Cura** o **PrusaSlicer**: corta el modelo en capas y genera las instrucciones (G-code). Aquí eliges el **relleno** (20 % es habitual), el grosor de capa y los **soportes** para las partes en voladizo.\n- **4. Imprimir:** desde minutos hasta horas.",
   "Materiales: **PLA** (fácil, biodegradable industrialmente, se deforma con el calor de un coche al sol), **PETG** (más resistente y flexible), **TPU** (flexible, para neumáticos).",
   "Consejos de diseño: deja **0,2–0,3 mm de holgura** en piezas que encajan; agujeros para tornillos M3 de unos 3,2–3,4 mm; evita voladizos de más de 45°; orienta la pieza para que la fuerza no separe las capas.",
   "### Corte láser",
   "Un láser corta o graba **láminas planas** (MDF, contrachapado, acrílico, cartón) siguiendo un dibujo **2D vectorial** (SVG o DXF) hecho en **Inkscape** o similar. Es muy rápido y preciso para chasis planos que se unen con tornillos o con **lengüetas** que encajan. Muchos *fab labs*, bibliotecas y universidades ofrecen acceso.",
   "### ¿Y si no tengo máquinas?",
   "Hay servicios en línea que imprimen o cortan tus diseños y los envían, y miles de diseños libres en repositorios en línea para descargar y adaptar."],
  pr: {m: ["computadora con navegador", "cuenta gratuita en Tinkercad"], p: ["Mide tu sensor HC-SR04 con una regla o calibre (largo, alto y diámetro de los cilindros).", "En Tinkercad 3D, diseña un soporte con dos agujeros para los cilindros (con 0,3 mm de holgura) y dos agujeros M3 para atornillarlo al chasis.", "Exporta el STL y ábrelo en un laminador para ver el tiempo de impresión.", "Si tienes acceso a una impresora, imprímelo y comprueba el ajuste."], e: "Un soporte diseñado a medida (impreso o listo para imprimir).", sim: "Toda la práctica se hace en la computadora."},
  sg: "Las impresoras 3D tienen piezas muy calientes (boquilla a más de 200 °C, cama a 60 °C) y los láseres pueden quemar la vista y provocar incendios: usa estas máquinas solo con supervisión y siguiendo las normas del taller o fab lab.",
  er: ["Diseñar agujeros del tamaño exacto del tornillo sin holgura.", "Imprimir piezas con voladizos grandes sin soportes."],
  q: [["¿Qué formato se exporta para imprimir en 3D?", ["STL", "MP3", "INO", "PDF"], 0, "El STL describe la superficie del objeto."],
   ["¿Qué programa convierte el modelo en capas e instrucciones para la impresora?", ["Laminador (Cura, PrusaSlicer)", "Arduino IDE", "KiCad", "Excel"], 0, "Genera el G-code."],
   ["¿Qué filamento es flexible, útil para neumáticos?", ["PLA", "PETG", "TPU", "MDF"], 2, "El TPU es elástico."],
   ["¿Qué tipo de dibujo necesita una cortadora láser?", ["Un modelo 3D", "Un dibujo 2D vectorial (SVG o DXF)", "Una foto", "Un código de Arduino"], 1, "Sigue las líneas del vector."],
   ["¿Cuánta holgura conviene dejar en piezas impresas que encajan?", ["0 mm", "0,2–0,3 mm", "5 mm", "1 cm"], 1, "La impresión no es perfectamente exacta."]]},
 {t: "Lazo abierto y lazo cerrado", h: 1, s: 1, p: "¿Por qué el horno de casa mantiene la temperatura pero una tostadora sencilla quema el pan si lo dejas más tiempo?",
  o: ["Diferenciar control en lazo abierto y cerrado.", "Identificar las partes de un sistema de control realimentado."],
  x: ["Controlar es conseguir que algo haga lo que queremos: una velocidad, una posición, una temperatura.",
   "### Lazo abierto",
   "El controlador da una orden **sin comprobar el resultado**. «Motor al 50 % durante 2 segundos» y se espera que el robot avance 50 cm. Funciona si nada cambia, pero cualquier perturbación (batería baja, una rampa, una alfombra) produce un error que nadie corrige. Ejemplos: la tostadora con temporizador, un motor paso a paso contando pasos, el robot que dibuja un cuadrado por tiempo (M14).",
   "### Lazo cerrado (realimentación)",
   "El controlador **mide** el resultado con un sensor, lo **compara** con lo deseado y **corrige** la acción continuamente. Partes:",
   "- **Referencia** (*setpoint*): el valor deseado (100 cm/s, 90°, 22 °C).\n- **Sensor:** mide el valor real (encoder, giroscopio, termómetro).\n- **Error = referencia − medida.**\n- **Controlador:** decide la acción a partir del error (todo-nada, PID…).\n- **Actuador:** motor, calefactor, servo.\n- **Sistema** o **planta:** lo que se controla (el robot, la habitación).",
   "El servo (M15) es un lazo cerrado en miniatura: su potenciómetro es el sensor. El termostato del horno, el control de crucero del coche y el equilibrio de un robot de dos ruedas son lazos cerrados.",
   "### Control todo-nada",
   "El más sencillo: si el error es positivo, actuar al máximo; si es negativo, apagar. Es el termostato clásico (con histéresis, M12). Funciona, pero produce **oscilaciones**: el valor sube y baja alrededor de la referencia. Para un control suave y preciso se usa el **PID** (siguiente lección)."],
  g: "lazo", k: "Lazo abierto: ordenar sin medir. Lazo cerrado: medir, comparar (error = referencia − medida) y corregir continuamente.",
  er: ["Pensar que un lazo cerrado no necesita sensor.", "Confundir referencia (lo deseado) con medida (lo real)."],
  q: [["Un robot que avanza 2 segundos al 50 % sin sensores usa control en…", ["Lazo abierto", "Lazo cerrado"], 0, "No comprueba el resultado."],
   ["¿Cómo se calcula el error en un lazo cerrado?", ["Medida − referencia × 2", "Referencia − medida", "Referencia + medida", "Medida / tiempo"], 1, "Lo deseado menos lo real."],
   ["Referencia de 100 cm/s y medida de 85 cm/s. ¿Error? (en cm/s)", {n: 15, tol: 0, u: "cm/s"}, null, "100 − 85 = 15 cm/s."],
   ["¿Qué elemento es imprescindible en un lazo cerrado?", ["Un LED", "Un sensor que mida el resultado", "Un relé", "WiFi"], 1, "Sin medida no hay realimentación."],
   ["¿Qué problema tiene el control todo-nada?", ["Es demasiado complejo", "Produce oscilaciones alrededor de la referencia", "No usa sensores", "Consume poco"], 1, "Por eso se usa PID para un control suave."]]},
 {t: "Control PID", h: 2, s: 1, p: "¿Cómo consigue un dron quedarse quieto en el aire aunque haya viento?",
  o: ["Explicar los términos proporcional, integral y derivativo.", "Programar un PID y ajustar sus constantes."],
  x: ["El **PID** es el controlador más usado en la industria y la robótica. Calcula la acción sumando tres términos a partir del error. Imagina un coche que quiere mantenerse en el centro de su carril:",
   "### P: proporcional al error actual",
   "**P = Kp × error.** Cuanto más lejos está del centro, más gira el volante. Es lo principal. Con Kp pequeño reacciona lento; con Kp grande reacciona fuerte, pero se pasa de largo y **oscila** (zigzag). Solo con P suele quedar un pequeño **error permanente**.",
   "### I: integral, la memoria del error",
   "**I = Ki × suma de los errores en el tiempo.** Si el coche lleva un rato desviado un poco hacia la derecha (por ejemplo, por viento lateral), la suma crece y añade una corrección extra hasta eliminar ese error permanente. Demasiado Ki provoca oscilaciones lentas y sobrepasos. Conviene **limitar** la suma (*anti-windup*) para que no crezca sin fin cuando el motor ya está al máximo.",
   "### D: derivada, la anticipación",
   "**D = Kd × cambio del error por unidad de tiempo.** Si el coche se está acercando muy rápido al centro, el término D frena la corrección antes de llegar, evitando pasarse. Amortigua las oscilaciones. Es sensible al ruido del sensor (filtra la medida si hace falta).",
   "### La fórmula",
   "**salida = Kp·e + Ki·∑e·dt + Kd·(e − e_anterior)/dt**, y luego se **limita** al rango del actuador (por ejemplo, −255 a 255 de PWM).",
   "### Ajustar el PID (método práctico)",
   "- **1.** Pon Ki = 0 y Kd = 0. Sube **Kp** hasta que el sistema responda rápido y empiece a oscilar; luego bájalo un poco (a la mitad, por ejemplo).\n- **2.** Sube **Kd** para reducir las oscilaciones y el sobrepaso.\n- **3.** Añade un **Ki** pequeño para eliminar el error permanente.\n- Cambia un valor cada vez y observa en el **trazador serie** la referencia y la medida.",
   "Usarás el PID para la velocidad de las ruedas (proyecto de este módulo) y para el seguidor de línea (M18). También existe la biblioteca **PID** de Brett Beauregard para Arduino."],
  k: "PID = Kp·error (presente) + Ki·suma (pasado) + Kd·cambio (futuro). Ajusta primero Kp, luego Kd y por último Ki, un valor cada vez.",
  c: {l: "cpp", t: "// Controlador PID genérico (no bloqueante)\nfloat Kp = 2.0, Ki = 0.5, Kd = 0.1;\nfloat integral = 0, errorAnterior = 0;\nunsigned long tPID = 0;\n\nfloat pid(float referencia, float medida) {\n  unsigned long ahora = millis();\n  float dt = (ahora - tPID) / 1000.0;\n  if (dt <= 0) dt = 0.001;\n  tPID = ahora;\n\n  float error = referencia - medida;\n  integral += error * dt;\n  integral = constrain(integral, -100, 100);        // anti-windup\n  float derivada = (error - errorAnterior) / dt;\n  errorAnterior = error;\n\n  float salida = Kp * error + Ki * integral + Kd * derivada;\n  return constrain(salida, -255, 255);              // límite del PWM\n}\n\n// Ejemplo de uso: velocidad de una rueda medida con un encoder\n// int pwm = pid(objetivoPulsosPorSegundo, pulsosPorSegundoMedidos);\n// motor(AIN1, AIN2, PWMA, pwm);"},
  pr: {m: ["robot 2WD con encoders", "computadora con el trazador serie"], p: ["Mide la velocidad de una rueda en pulsos por segundo cada 50 ms.", "Implementa el PID para mantener una velocidad objetivo (por ejemplo, 40 pulsos/s).", "Envía referencia y medida al trazador serie.", "Ajusta Kp, luego Kd y luego Ki, anotando lo que observas en cada cambio.", "Frena la rueda suavemente con el dedo y observa cómo el PID compensa."], e: "La velocidad vuelve a la referencia tras una perturbación, sin oscilar mucho.", sim: "Existen simuladores de PID en línea donde ver el efecto de cada constante."},
  er: ["Ajustar las tres constantes a la vez.", "No limitar la integral y obtener sobrepasos enormes."],
  q: [["¿Qué término del PID elimina el error permanente?", ["Proporcional", "Integral", "Derivativo", "Ninguno"], 1, "Acumula el error en el tiempo."],
   ["¿Qué término amortigua las oscilaciones anticipando?", ["Proporcional", "Integral", "Derivativo"], 2, "Reacciona a la velocidad de cambio del error."],
   ["Con Kp = 3 y un error de 10, ¿cuánto vale el término P?", {n: 30, tol: 0, u: ""}, null, "P = Kp × error = 30."],
   ["¿Qué ocurre con un Kp demasiado grande?", ["El sistema no reacciona", "Oscila y se pasa de largo", "Se apaga", "Nada"], 1, "Corrige con demasiada fuerza."],
   ["¿Qué constante se ajusta primero en el método práctico?", ["Ki", "Kd", "Kp", "Todas a la vez"], 2, "Primero Kp, luego Kd, después Ki."]]},
 {t: "Máquinas de estados", h: 1.5, s: 1, p: "¿Cómo programas un robot que busca, persigue, esquiva y vuelve a casa sin que el código se convierta en un caos de if?",
  o: ["Modelar un comportamiento como estados y transiciones.", "Programar una máquina de estados con switch y millis()."],
  x: ["A medida que un robot hace más cosas, el código lleno de `if` anidados y `delay()` se vuelve imposible de entender. Una **máquina de estados** organiza el comportamiento así:",
   "- El robot está siempre en **un estado** (por ejemplo, BUSCAR, AVANZAR, ESQUIVAR, PARADO).\n- En cada estado hace **una cosa** concreta.\n- Unos **eventos** o condiciones provocan **transiciones** a otro estado (obstáculo cerca → ESQUIVAR; ha pasado 1 s esquivando → AVANZAR).",
   "### Diagrama de estados",
   "Se dibuja con **círculos** (estados) y **flechas** con la condición de cada transición. Hacer el dibujo antes de programar aclara muchísimo la lógica y revela casos olvidados (¿qué pasa si se detecta un obstáculo mientras se gira?).",
   "### Programarla",
   "- Un tipo `enum` con los estados y una variable `estado`.\n- Un `switch (estado)` en `loop()`: cada `case` ejecuta la acción del estado y comprueba sus transiciones.\n- Una variable con el **momento de entrada** al estado (millis()) para medir cuánto tiempo lleva en él, **sin delay()**.\n- Una función `cambiarA(nuevoEstado)` que actualiza el estado, guarda el momento y puede hacer acciones de entrada (parar motores, encender un LED, imprimir el cambio por serie para depurar).",
   "### Ventajas",
   "El robot nunca se bloquea (sigue leyendo sensores en todos los estados), el código es fácil de leer y ampliar (añadir un estado BATERÍA_BAJA es añadir un case), y es fácil depurar viendo por el monitor serie en qué estado está.",
   "Los robots de los Niveles 4 y 5 están todos organizados como máquinas de estados. La puerta automática del ejemplo (CERRADA, ABRIENDO, ABIERTA, CERRANDO) es un caso clásico."],
  c: {l: "cpp", t: "// Puerta automática como máquina de estados\nenum Estado { CERRADA, ABRIENDO, ABIERTA, CERRANDO };\nEstado estado = CERRADA;\nunsigned long tEntrada = 0;\n\nvoid cambiarA(Estado nuevo) {\n  estado = nuevo;\n  tEntrada = millis();\n  Serial.print(\"Estado: \"); Serial.println(nuevo);\n}\n\nvoid loop() {\n  bool presencia = digitalRead(PIR) == HIGH;\n  unsigned long t = millis() - tEntrada;      // tiempo en el estado actual\n\n  switch (estado) {\n    case CERRADA:\n      if (presencia) cambiarA(ABRIENDO);\n      break;\n    case ABRIENDO:\n      moverPuerta(+1);\n      if (finalAbierta()) { pararPuerta(); cambiarA(ABIERTA); }\n      break;\n    case ABIERTA:\n      if (presencia) tEntrada = millis();      // alguien sigue: reinicia la espera\n      else if (t > 5000) cambiarA(CERRANDO);\n      break;\n    case CERRANDO:\n      moverPuerta(-1);\n      if (presencia) cambiarA(ABRIENDO);       // ¡seguridad: no cerrar sobre alguien!\n      else if (finalCerrada()) { pararPuerta(); cambiarA(CERRADA); }\n      break;\n  }\n}"},
  pr: {m: ["Arduino", "servo", "PIR o pulsador", "LED"], p: ["Dibuja el diagrama de estados de la puerta automática.", "Implementa la puerta con un servo (0° cerrada, 90° abierta) moviéndolo grado a grado en ABRIENDO y CERRANDO.", "Usa un pulsador o un PIR como sensor de presencia.", "Enciende un LED de aviso mientras la puerta se mueve.", "Comprueba que si hay presencia mientras se cierra, vuelve a abrirse."], e: "La puerta se abre, espera y se cierra, y se reabre si detecta a alguien.", sim: "Wokwi con un servo, un PIR y un LED."},
  er: ["Usar delay() dentro de los estados.", "Olvidar transiciones de seguridad (reabrir si hay alguien)."],
  q: [["En una máquina de estados, ¿en cuántos estados está el sistema a la vez?", ["En todos", "En uno solo", "En ninguno", "En dos"], 1, "Siempre en un único estado."],
   ["¿Qué provoca un cambio de estado?", ["Un delay", "Un evento o condición (transición)", "Un error de compilación", "Nada"], 1, "Las transiciones se activan por condiciones."],
   ["¿Qué estructura de C++ se usa típicamente para la máquina de estados?", ["for", "switch con un enum", "while(true)", "#include"], 1, "Un case por estado."],
   ["¿Cómo se mide el tiempo en un estado sin bloquear?", ["delay()", "Guardando millis() al entrar y restando", "Con tone()", "No se puede"], 1, "millis() − tEntrada."],
   ["¿Por qué es importante la transición CERRANDO → ABRIENDO si hay presencia?", ["Por estética", "Por seguridad: no cerrar sobre una persona", "Para ahorrar energía", "No es importante"], 1, "Es una transición de seguridad."]]},
 {t: "Integración y pruebas", h: 1, p: "Cada parte de tu robot funciona por separado, pero juntas fallan. ¿Qué haces?",
  o: ["Integrar subsistemas paso a paso.", "Diseñar y documentar pruebas de un robot."],
  x: ["**Integrar** es unir mecánica, electrónica y software en un sistema que funcione. Es la fase donde aparecen los problemas que no se veían por separado: ruido de los motores en los sensores, caídas de voltaje, falta de memoria, piezas que chocan, cables que se enganchan.",
   "### Integración incremental",
   "No conectes todo a la vez. Sigue un orden y **prueba después de cada paso**:",
   "- **1. Alimentación:** batería, interruptor, fusible y reguladores. Mide los voltajes sin nada conectado.\n- **2. Controlador:** carga un Blink alimentado desde la batería.\n- **3. Actuadores:** motores con las ruedas en el aire; comprueba el sentido y que el Arduino no se reinicia.\n- **4. Sensores, uno a uno:** comprueba sus lecturas **con los motores en marcha** (el ruido aparece aquí).\n- **5. Comportamiento:** la máquina de estados completa.\n- **6. Pruebas en el entorno real.**",
   "Guarda una **versión del código** que funciona después de cada paso (M02).",
   "### Programas de prueba",
   "Ten a mano pequeños programas de diagnóstico: uno que mueve cada motor por separado, uno que imprime todos los sensores, un escáner I2C. Muchos robots incluyen un **modo prueba** que se activa con un botón al arrancar.",
   "### Lista de comprobación antes de cada sesión",
   "Batería cargada; tornillos y ruedas apretados; cables firmes (prueba de tirón); sensores limpios y bien orientados; interruptor accesible; espacio de pruebas despejado y sin escaleras cerca.",
   "### Probar con método",
   "Define pruebas con **criterios medibles** (como en el proyecto: «avanza 1 m con error < 2 cm»), repítelas varias veces (un éxito puede ser suerte), anota los resultados en una tabla y cambia **una sola cosa** entre pruebas. Graba vídeos: muchas veces revelan lo que a simple vista no se ve."],
  k: "Integra paso a paso (alimentación → controlador → actuadores → sensores → comportamiento) y prueba después de cada uno, con criterios medibles y repetidos.",
  er: ["Montarlo todo y probar por primera vez con el robot completo.", "Probar los sensores solo con los motores apagados."],
  q: [["¿Qué se integra primero en un robot?", ["Los sensores", "La alimentación", "El comportamiento", "La pintura"], 1, "Sin una alimentación correcta, nada funciona bien."],
   ["¿Por qué probar los sensores con los motores en marcha?", ["Para que vayan más rápido", "Porque el ruido de los motores puede alterar las lecturas", "Para gastar batería", "No hace falta"], 1, "Muchos problemas solo aparecen así."],
   ["¿Qué es un criterio de prueba medible?", ["«Funciona bien»", "«Avanza 1 m con un error menor de 2 cm»", "«Es bonito»", "«Va rápido»"], 1, "Tiene un número comprobable."],
   ["¿Por qué repetir una prueba varias veces?", ["Para cansarse", "Porque un solo éxito puede ser casualidad", "Porque lo exige el Arduino", "No hace falta"], 1, "La repetición da fiabilidad."],
   ["¿Qué hace un escáner I2C en la integración?", ["Mueve motores", "Comprueba qué dispositivos I2C responden", "Mide la batería", "Carga el programa"], 1, "Es un programa de diagnóstico."]]}
 ]}
);
